// save the current localStorage, dispose the window, create a fresh one, restore
// localStorage, then re-initialize the app so it loads from the persisted state.
async reloadApp() {
  if (!this.window) throw new Error('verification support: reloadApp() before the app was loaded');
  // Snapshot the current localStorage contents
  const saved = {};
  const storage = this.window.localStorage;
  for (let i = 0; i < storage.length; i++) {
    const key = storage.key(i);
    saved[key] = storage.getItem(key);
  }
  // Dispose the current window
  await this.disposeApp();
  // Load a fresh app
  this.loadApp();
  // Restore localStorage before the app reads it
  const freshStorage = this.window.localStorage;
  Object.keys(saved).forEach(key => freshStorage.setItem(key, saved[key]));
